import axios from './axiosSetup';

const EVENEMENT_API_BASE_URL = process.env.REACT_APP_API_URL + 'evenement';

class EvenementenService {

  GetAll() {
    return axios.get(`${EVENEMENT_API_BASE_URL}/All`);
  }

  GetAllFirstInSeries() {
    return axios.get(`${EVENEMENT_API_BASE_URL}/GetFirstInSeries`);
  }

  GetByID(id) {
    return axios.get(`${EVENEMENT_API_BASE_URL}/Get/${id}`);
  }

  Nieuw(evenement) {
    return axios.post(`${EVENEMENT_API_BASE_URL}/nieuwevenement`, evenement);
  }

  Delete(evenementID) {
    return axios.delete(`${EVENEMENT_API_BASE_URL}/Delete/${evenementID}`);
  }

  DeleteSeries(evenementID) {
    return axios.delete(`${EVENEMENT_API_BASE_URL}/Delete/Series/${evenementID}`);
  }

  UpdateSeries(evenement) {
    return axios.patch(`${EVENEMENT_API_BASE_URL}/Update/Series`, evenement);
  }

  Update(evenement) {
    return axios.patch(`${EVENEMENT_API_BASE_URL}/Update`, evenement);
  }

}

export default new EvenementenService();
