import React, { useState, useRef, useEffect } from "react";
import { InputText } from "primereact/inputtext";
import { Messages } from "primereact/messages";
import { Dropdown } from "primereact/dropdown";
import * as XLSX from "xlsx";

import GroepService from "../../../Services/GroepService";
import LidService from "../../../Services/LidService";
import ExcelBulkUpload from "../../../Services/ExcelBulkUpload";

export default function NieuwLid() {
  const [Groepen, SetGroepen] = useState(null);
  const [SelectedGroep, SetGroep] = useState("");
  const [Lid, setLid] = useState({
    voornaam: "",
    achternaam: "",
    email: "",
    groep: "",
  });

  const msgs = useRef(null);
  const fileInputRef = useRef(null);

  useEffect(() => {
    GroepService.GetAll().then((result) => {
      if (result && result.data && result.data.payload) {
        SetGroepen(result.data.payload);
      }
    });
  }, []);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setLid((prevState) => ({
      ...prevState,
      [name]: value,
    }));
  };

  const Upload = (e) => {
    e.preventDefault();

    msgs.current.show({
      severity: "info",
      detail: "Lid aan het toevoegen, dit kan even duren",
      sticky: false,
    });

    // Assign selected group safely
    Lid.groep = SelectedGroep && SelectedGroep.id ? SelectedGroep.id : "";

    LidService.nieuw(Lid).then((result) => {
      try {
        if (result && result.data) {
          if (result.data.type === "SUCCES") {
            msgs.current.show({
              severity: "success",
              detail: "Lid toevoegen gelukt!",
              sticky: true,
            });
          } else {
            const details =
              result.data.payload && result.data.payload.details
                ? result.data.payload.details
                : [];
            const combinedError =
              (details.length > 0 ? details.join(", ") : "") ||
              (result.data.payload && result.data.payload.message) ||
              "Onbekende fout";
            msgs.current.show({
              severity: "error",
              detail: combinedError,
              sticky: true,
            });
          }
        } else {
          msgs.current.show({
            severity: "error",
            detail: "Onverwachte fout bij het toevoegen van lid",
            sticky: true,
          });
        }
      } catch (err) {
        console.error(err);
        msgs.current.show({
          severity: "error",
          detail: "Onverwachte fout bij het toevoegen van lid",
          sticky: true,
        });
      }
    });
  };

  const UploadExcel = async (e) => {
    e.preventDefault();
    const file = fileInputRef.current.files[0];
    if (!file) {
      msgs.current.show({
        severity: "warn",
        detail: "Selecteer eerst een Excel-bestand",
        sticky: true,
      });
      return;
    }

    msgs.current.show({
      severity: "info",
      detail: "Excel upload bezig. Dit kan even duren.",
      sticky: true,
    });

    try {
      const result = await ExcelBulkUpload.handleFile(file);
      console.log("Excel result:", result);

      if (result && result.data) {
        if (result.data.type === "SUCCES") {
          msgs.current.show({
            severity: "success",
            detail: "Excel upload voltooid! Records toegevoegd.",
            sticky: true,
          });
        } else {
          const details =
            result.data.payload && result.data.payload.details
              ? result.data.payload.details
              : [];
          const combinedError =
            (details.length > 0 ? details.join(", ") : "") ||
            (result.data.payload && result.data.payload.message) ||
            "Onbekende fout";

          msgs.current.show({
            severity: "error",
            detail: combinedError,
            sticky: true,
          });
        }
      } else {
        msgs.current.show({
          severity: "error",
          detail: "Onverwachte fout bij Excel upload",
          sticky: true,
        });
      }
    } catch (error) {
      msgs.current.show({
        severity: "error",
        detail: "Fout bij het uploaden van Excel",
        sticky: true,
      });
      console.error(error);
    }
  };

  const downloadTemplate = () => {
    const data = [["Voornaam", "Achternaam", "Email", "Groep naam"]];
    const worksheet = XLSX.utils.aoa_to_sheet(data);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "Template");
    XLSX.writeFile(workbook, "LidUploadTemplate.xlsx");
  };

  return (
    <>
      <form onSubmit={Upload}>
        <div className="Auth-form-content">
          <h3 className="Auth-form-title">Nieuw Lid</h3>
          <Messages ref={msgs} />

          <div className="form-group mt-3">
            <label>Voornaam</label>
            <InputText
              name="voornaam"
              onChange={handleChange}
              className="form-control mt-1"
              placeholder="Enter voornaam"
            />
          </div>

          <div className="form-group mt-3">
            <label>Achternaam</label>
            <InputText
              name="achternaam"
              onChange={handleChange}
              className="form-control mt-1"
              placeholder="Enter achternaam"
            />
          </div>

          <div className="form-group mt-3">
            <label>Email </label>
            <InputText
              name="email"
              onChange={handleChange}
              className="form-control mt-1"
              placeholder="voorbeeld@Email.nl"
            />
          </div>

          <div className="form-group mt-3">
            <label>Groep</label>
            <Dropdown
              name="groep"
              onChange={(e) => SetGroep(e.value)}
              value={SelectedGroep}
              optionLabel="naam"
              options={Groepen}
              className="form-control mt-1"
              placeholder="selecteer groep"
            />
          </div>

          <div className="d-grid gap-2 mt-3">
            <button type="submit" className="btn btn-primary">
              Voeg toe
            </button>
          </div>

          <h3 className="Auth-form-title">Vanuit Excel</h3>

          <div className="form-group mt-4">
            <label>Upload Excel</label>
            <a
              style={{
                marginLeft: "4vw",
                cursor: "pointer",
                textDecoration: "underline",
              }}
              onClick={downloadTemplate}
            >
              Download template
            </a>

            <input
              type="file"
              ref={fileInputRef}
              accept=".xlsx,.xls"
              className="form-control mt-1"
            />
          </div>

          <div className="d-grid gap-2 mt-2">
            <button
              type="button"
              className="btn btn-success"
              onClick={UploadExcel}
            >
              Upload Excel
            </button>
          </div>
        </div>
      </form>
    </>
  );
}
