import axios from 'axios';
import SessionHandler from '../Sessionhandler/SessionHandler';
import { handleAxiosError } from './RequestErrorHandeling';

axios.defaults.headers.common.Authorization = 'Bearer ' + SessionHandler.getToken();
axios.defaults.headers.common['ClubID'] = SessionHandler.GetClub();

const DEELNEMER_API_BASE_URL = process.env.REACT_APP_API_URL + 'Deelnemer';

class DeelnemerService {

  GetDeelnemers(EvenementID) {
    return axios
      .get(`${DEELNEMER_API_BASE_URL}/getdeelnemers/${EvenementID}`)
      .catch(handleAxiosError);
  }

  GetByUserID(ID) {
    return axios
      .get(`${DEELNEMER_API_BASE_URL}/getevenementen/${ID}`, {
        headers: {
          Authorization: 'Bearer ' + SessionHandler.getToken(),
          ClubID: SessionHandler.GetClub(),
        },
      })
      .catch(handleAxiosError);
  }

  GetDeelnemersByID(ID) {
    return axios
      .get(`${DEELNEMER_API_BASE_URL}/getdeelnemers/${ID}`, {
        headers: {
          Authorization: 'Bearer ' + SessionHandler.getToken(),
          ClubID: SessionHandler.GetClub(),
        },
      })
      .catch(handleAxiosError);
  }

  UpdateAangemeld(LidId, Evenenementid, niewestatus) {
    const data = { lidid: LidId, evenementid: Evenenementid, status: niewestatus };
    return axios
      .patch(`${DEELNEMER_API_BASE_URL}/Aangemeld`, data, {
        headers: {
          Authorization: 'Bearer ' + SessionHandler.getToken(),
          ClubID: SessionHandler.GetClub(),
        },
      })
      .catch(handleAxiosError);
  }

  AddDeelnemer(Lid, EvenementID, Groep, Type, Reeks) {
    const data = {
      lidid: Lid,
      evenementid: EvenementID,
      groep: Groep,
      type: Type,
      series: Reeks,
    };
    return axios
      .patch(`${DEELNEMER_API_BASE_URL}/extradeelnemer`, data, {
        headers: {
          Authorization: 'Bearer ' + SessionHandler.getToken(),
          ClubID: SessionHandler.GetClub(),
        },
      })
      .catch(handleAxiosError);
  }

  Delete(lid, evenement) {
    const data = {
      lidid: lid.lid.id,
      evenementid: evenement,
    };
    return axios({
      method: 'delete',
      url: `${DEELNEMER_API_BASE_URL}/Delete`,
      data,
      headers: { 'Content-Type': 'application/json' },
    }).catch(handleAxiosError);
  }

  UpdateAanwezigheid(LidId, Evenenementid, niewestatus) {
    const data = {
      lidid: LidId,
      evenementid: Evenenementid,
      aanwezigheid: niewestatus,
    };
    return axios
      .patch(`${DEELNEMER_API_BASE_URL}/aanwezigheid`, data, {
        headers: {
          Authorization: 'Bearer ' + SessionHandler.getToken(),
          ClubID: SessionHandler.GetClub(),
        },
      })
      .catch(handleAxiosError);
  }

}

export default new DeelnemerService();
